import { useRef } from "react";
import { useThreeJS } from "../hooks/useThreeJS";
import AnimationControls from "./AnimationControls";

export default function EarthViewer() {
  const containerRef = useRef(null);
  const {
    selectedCountry,
    hoveredCountry,
    isAnimating,
    startAutoAnimation,
    stopAutoAnimation,
  } = useThreeJS(containerRef);

  return (
    <div style={{ position: "relative" }}>
      <div ref={containerRef} />

      {/* Country Info Overlay */}
      {selectedCountry && (
        <div
          style={{
            position: "absolute",
            top: "20px",
            left: "20px",
            background: "rgba(0, 0, 0, 0.8)",
            color: "white",
            padding: "15px",
            borderRadius: "8px",
            fontSize: "16px",
            fontFamily: "Arial, sans-serif",
            zIndex: 1000,
          }}
        >
          <h3 style={{ margin: "0 0 5px 0" }}>Selected Country</h3>
          <p style={{ margin: "0" }}>{selectedCountry.countryName}</p>
          <p style={{ margin: "5px 0 0 0", fontSize: "14px", opacity: 0.8 }}>
            Code: {selectedCountry.countryCode}
          </p>
        </div>
      )}

      {/* Hover Info */}
      {hoveredCountry && !selectedCountry && (
        <div
          style={{
            position: "absolute",
            top: "20px",
            left: "20px",
            background: "rgba(255, 255, 255, 0.9)",
            color: "black",
            padding: "10px",
            borderRadius: "5px",
            fontSize: "14px",
            fontFamily: "Arial, sans-serif",
            zIndex: 1000,
          }}
        >
          {hoveredCountry.countryName}
        </div>
      )}

      {/* Animation Status */}
      {isAnimating && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            background: "rgba(0, 0, 0, 0.7)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "20px",
            fontSize: "14px",
            fontFamily: "Arial, sans-serif",
            zIndex: 1000,
          }}
        >
          Animating to country...
        </div>
      )}

      {/* Animation Controls */}
      <AnimationControls
        startAutoAnimation={startAutoAnimation}
        stopAutoAnimation={stopAutoAnimation}
      />
    </div>
  );
}
